# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import uncovered_gaps

OPEN = parse_span("09:00-17:00")

class UncoveredGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        worked = [parse_span("09:00-12:00"), parse_span("13:00-17:00")]
        self.assertEqual(uncovered_gaps(worked, OPEN), ["gap 12:00-13:00 (60 min)"])

    def test_gaps_at_both_ends(self):
        worked = [parse_span("10:00-16:30")]
        self.assertEqual(
            uncovered_gaps(worked, OPEN),
            ["gap 09:00-10:00 (60 min)", "gap 16:30-17:00 (30 min)"],
        )

    def test_nobody_working_gives_whole_day(self):
        self.assertEqual(uncovered_gaps([], OPEN), ["gap 09:00-17:00 (480 min)"])

    def test_full_coverage_gives_nothing(self):
        worked = [parse_span("09:00-13:00"), parse_span("13:00-17:00")]
        self.assertEqual(uncovered_gaps(worked, OPEN), [])

    def test_overlapping_and_unordered_spans(self):
        worked = [parse_span("14:00-17:00"), parse_span("09:00-12:00"), parse_span("11:00-13:00")]
        self.assertEqual(uncovered_gaps(worked, OPEN), ["gap 13:00-14:00 (60 min)"])

    def test_span_outside_opening_hours_raises(self):
        for worked in ("08:00-10:00", "16:00-18:00"):
            with self.assertRaises(ValueError):
                uncovered_gaps([parse_span(worked)], OPEN)
